#!/usr/bin/env python3
"""Generate the component docs and indexes of docs/reference/ from docs/reference/data/*.json.

The system docs (docs/reference/systems/*.md) and folder docs (docs/reference/folders/*.md) are written by hand;
the component docs, the access matrix and the indexes are generated by this script, so every system that touches a
component shows up in that component's doc with the same access information as in the system doc.

Usage: python3 tools/gen_reference_docs.py [--check]
  --check  exit 1 when a generated file is out of date or the data is inconsistent (no files written)
"""

import json
import re
import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
REF = ROOT / "docs" / "reference"
DATA = REF / "data"
GENERATED = "<!-- Generated by tools/gen_reference_docs.py from docs/reference/data/*.json. Do not edit by hand. -->"

ACCESS_ORDER = {"write": 0, "readwrite": 1, "read": 2}


def slug(name: str) -> str:
    """File name of a component or system doc: C++ qualifiers and template brackets become dashes."""
    s = re.sub(r"[^A-Za-z0-9_]+", "-", name).strip("-")
    return s or "unnamed"


def src_link(path: str, up: str = "../../../") -> str:
    return f"[`{path}`]({up}{path})"


def cell(text) -> str:
    if text is None:
        return ""
    if isinstance(text, list):
        text = "; ".join(str(t) for t in text)
    return str(text).replace("|", "\\|").replace("\n", " ").strip()


def load():
    systems, components, access, problems = {}, {}, [], []
    for f in sorted(DATA.glob("*.json")):
        try:
            d = json.loads(f.read_text())
        except json.JSONDecodeError as e:
            problems.append(f"{f.name}: invalid JSON: {e}")
            continue
        area = f.stem
        for s in d.get("systems", []):
            s["area"] = area
            if s["name"] in systems:
                problems.append(f"{f.name}: system {s['name']} also defined in {systems[s['name']]['area']}.json")
            systems[s["name"]] = s
        for c in d.get("components", []):
            c["area"] = area
            if c["name"] in components:
                problems.append(f"{f.name}: component {c['name']} also defined in {components[c['name']]['area']}.json")
            components[c["name"]] = c
        for a in d.get("access", []):
            a["area"] = area
            if a.get("access") not in ACCESS_ORDER:
                problems.append(f"{f.name}: {a.get('system')} -> {a.get('component')}: bad access {a.get('access')!r}")
            access.append(a)
    for a in access:
        if a["system"] not in systems:
            problems.append(f"{a['area']}.json: access by unknown system {a['system']}")
    return systems, components, access, problems


def access_label(a) -> str:
    label = f"`{a['access']}`"
    for l in a.get("lifecycle") or []:
        label += f" +{l}"
    return label


def system_link(name, systems, up="../systems/"):
    return f"[{name}]({up}{slug(name)}.md)" if name in systems else name


def component_doc(name, c, entries, systems):
    out = [GENERATED, "", f"# {name}", ""]
    if c:
        meta = [f"**Kind:** {c.get('kind', 'component')}", f"**Registry:** {c.get('registry', '?')}"]
        if c.get("folder"):
            meta.append(f"**Folder:** [`{c['folder']}/`](../folders/{slug(c['folder'].replace('/', '-'))}.md)")
        out.append("> " + " · ".join(meta))
        if c.get("sources"):
            out.append("> **Source:** " + ", ".join(src_link(p) for p in c["sources"]))
        out += ["", "## Summary", "", c.get("summary") or "", ""]
        if c.get("description"):
            out += ["## Description", "", c["description"], ""]
        if c.get("scene_json"):
            sj = c["scene_json"]
            out += ["## Scene JSON", "", sj if isinstance(sj, str) else "```json\n" + json.dumps(sj, indent=2) + "\n```", ""]
        fields = c.get("fields") or []
        out += ["## Fields", ""]
        if fields:
            out += ["| Field | Type | Default | Description |", "|---|---|---|---|"]
            for fl in fields:
                out.append(f"| `{cell(fl.get('name'))}` | `{cell(fl.get('type'))}` | {cell(fl.get('default'))} | {cell(fl.get('desc'))} |")
        else:
            out.append("None (tag, opaque type or no data members).")
        out.append("")
    else:
        out += ["> **Kind:** external or undocumented type", "",
                "## Summary", "",
                "Defined outside the documented source areas (third-party library or standard type). "
                "It appears here because systems store or read it in a registry.", ""]

    out += ["## Systems touching this component", ""]
    if not entries:
        out += ["None found.", ""]
    else:
        writers = sorted({e["system"] for e in entries if e["access"] in ("write", "readwrite")})
        readers = sorted({e["system"] for e in entries if e["access"] in ("read", "readwrite")})
        creators = sorted({e["system"] for e in entries if set(e.get("lifecycle") or []) & {"create", "emplace_ctx"}})
        destroyers = sorted({e["system"] for e in entries if set(e.get("lifecycle") or []) & {"destroy", "remove"}})
        out += [
            f"- **Writers:** {', '.join(system_link(s, systems) for s in writers) or 'None'}",
            f"- **Readers:** {', '.join(system_link(s, systems) for s in readers) or 'None'}",
            f"- **Creates / emplaces:** {', '.join(system_link(s, systems) for s in creators) or 'None'}",
            f"- **Destroys / removes:** {', '.join(system_link(s, systems) for s in destroyers) or 'None'}",
            "",
            "| System | Kind | Registry | Access | Phase | Details |",
            "|---|---|---|---|---|---|",
        ]
        for e in sorted(entries, key=lambda e: (e["system"], ACCESS_ORDER.get(e["access"], 9), e.get("phase", ""))):
            kind = systems.get(e["system"], {}).get("kind", "?")
            out.append(f"| {system_link(e['system'], systems)} | {kind} | {cell(e.get('registry'))} | {access_label(e)} | "
                       f"{cell(e.get('phase'))} | {cell(e.get('details'))} |")
        out.append("")

        out += ["## Side effects per system", ""]
        any_effect = False
        by_sys = defaultdict(list)
        for e in entries:
            for se in e.get("side_effects") or []:
                if se not in by_sys[e["system"]]:
                    by_sys[e["system"]].append(se)
        for s in sorted(by_sys):
            any_effect = True
            out.append(f"- **{system_link(s, systems)}**")
            out += [f"  - {se}" for se in by_sys[s]]
        if not any_effect:
            out.append("None recorded beyond the field accesses above.")
        out.append("")
    return "\n".join(out)


def build():
    systems, components, access, problems = load()
    files = {}

    by_comp = defaultdict(list)
    for a in access:
        by_comp[a["component"]].append(a)
    names = sorted(set(components) | set(by_comp), key=str.lower)

    for n in names:
        files[REF / "components" / f"{slug(n)}.md"] = component_doc(n, components.get(n), by_comp.get(n, []), systems)

    # Index of components
    out = [GENERATED, "", "# Components and context variables", "",
           "Every type stored in a registry (per-entity component, tag, or `reg.ctx()` variable), with the systems that touch it.", "",
           "| Component | Kind | Registry | Writers | Readers | Summary |", "|---|---|---|---|---|---|"]
    for n in names:
        c = components.get(n, {})
        e = by_comp.get(n, [])
        w = len({x["system"] for x in e if x["access"] in ("write", "readwrite")})
        r = len({x["system"] for x in e if x["access"] in ("read", "readwrite")})
        out.append(f"| [{n}]({slug(n)}.md) | {c.get('kind', 'external')} | {cell(c.get('registry', '?'))} | {w} | {r} | {cell(c.get('summary', ''))} |")
    files[REF / "components" / "README.md"] = "\n".join(out) + "\n"

    # Index of systems
    out = [GENERATED, "", "# Systems, passes and services", "",
           "Hand-written docs, one per system. Kinds: `system` (a `dy::System` in a `SystemSet` lane), `pass` (renderer scene pass), "
           "`service` (other code that reads or writes registry state).", "",
           "| System | Kind | Registry name | Scope | Lane | Folder | Summary |", "|---|---|---|---|---|---|---|"]
    for n in sorted(systems, key=str.lower):
        s = systems[n]
        doc = REF / "systems" / f"{slug(n)}.md"
        if not doc.exists():
            problems.append(f"system {n} has no doc at {doc.relative_to(ROOT)}")
        out.append(f"| [{n}]({slug(n)}.md) | {s.get('kind', '')} | {cell(s.get('registry_name') or '—')} | {cell(s.get('scope'))} | "
                   f"{cell(s.get('lane'))} | `{cell(s.get('folder'))}` | {cell(s.get('summary'))} |")
    files[REF / "systems" / "README.md"] = "\n".join(out) + "\n"

    # Access matrix: system x component
    sys_names = sorted({a["system"] for a in access}, key=str.lower)
    out = [GENERATED, "", "# Access matrix", "",
           "Rows are systems, columns components. `R` read, `W` write, `RW` read-write; `+` marks create / emplace, "
           "`-` destroy / remove. Phases are merged; see each component doc for details.", ""]
    grid = defaultdict(dict)
    for a in access:
        cur = grid[a["system"]].get(a["component"], set())
        cur.add(a["access"])
        for l in a.get("lifecycle") or []:
            cur.add(l)
        grid[a["system"]][a["component"]] = cur

    def code(s):
        rw = ("readwrite" in s) or ("read" in s and "write" in s)
        t = "RW" if rw else "W" if "write" in s else "R" if "read" in s else ""
        if s & {"create", "emplace_ctx"}:
            t += "+"
        if s & {"destroy", "remove"}:
            t += "-"
        return t

    # One table per area keeps the tables readable
    for area in sorted({systems[s]["area"] for s in sys_names if s in systems}):
        rows = [s for s in sys_names if systems.get(s, {}).get("area") == area]
        cols = sorted({c for s in rows for c in grid[s]}, key=str.lower)
        out += [f"## {area}", "", "| System | " + " | ".join(f"[{c}](../components/{slug(c)}.md)" for c in cols) + " |",
                "|---|" + "---|" * len(cols)]
        for s in rows:
            out.append(f"| [{s}]({slug(s)}.md) | " + " | ".join(code(grid[s].get(c, set())) for c in cols) + " |")
        out.append("")
    files[REF / "systems" / "access-matrix.md"] = "\n".join(out)

    # Index of folders (hand-written docs)
    out = [GENERATED, "", "# Folders", "", "One summary per source folder.", ""]
    for f in sorted((REF / "folders").glob("*.md")):
        if f.name == "README.md":
            continue
        title = f.read_text().splitlines()[0].lstrip("# ").strip()
        out.append(f"- [{title}]({f.name})")
    files[REF / "folders" / "README.md"] = "\n".join(out) + "\n"

    return files, problems


def check_links(files):
    """Relative links of every reference doc must resolve."""
    problems = []
    docs = {p: t for p, t in files.items()}
    for p in REF.rglob("*.md"):
        docs.setdefault(p, p.read_text())
    for p, text in docs.items():
        for target in re.findall(r"\]\(([^)#\s]+)(?:#[^)]*)?\)", text):
            if re.match(r"^[a-z]+://", target):
                continue
            if not (p.parent / target).resolve().exists():
                problems.append(f"{p.relative_to(ROOT)}: broken link {target}")
    return problems


def main():
    check = "--check" in sys.argv
    files, problems = build()
    problems += check_links(files)
    stale = []
    for path, text in files.items():
        if not text.endswith("\n"):
            text += "\n"
        if path.exists() and path.read_text() == text:
            continue
        stale.append(path)
        if not check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
    if not check:
        # Generated component docs whose component vanished from the data
        for p in (REF / "components").glob("*.md"):
            if p not in files and p.read_text().startswith(GENERATED):
                p.unlink()
                print(f"removed {p.relative_to(ROOT)}")
    for p in problems:
        print("problem:", p)
    if check:
        for p in stale:
            print("stale:", p.relative_to(ROOT))
        sys.exit(1 if (stale or problems) else 0)
    print(f"{len(stale)} file(s) written, {len(problems)} problem(s)")


if __name__ == "__main__":
    main()
